import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.gtmkOXzY.js";const p=JSON.parse('{"title":"Languages and text","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/languages.md","filePath":"ms-flightsim/languages.md","lastUpdated":null}'),n={name:"ms-flightsim/languages.md"};function l(o,e,h,d,r,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="languages-and-text" tabindex="-1">Languages and text <a class="header-anchor" href="#languages-and-text" aria-label="Permalink to &quot;Languages and text&quot;">​</a></h1><p>MS_FlightSim ships in eight languages; you pick one for the whole server, can change any single line of text, and can add a language of your own.</p><h2 id="choosing-the-language" tabindex="-1">Choosing the language <a class="header-anchor" href="#choosing-the-language" aria-label="Permalink to &quot;Choosing the language&quot;">​</a></h2><p>Set <code>Config.Language</code> on the first lines of <code>config.lua</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Language</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;de&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Code</th><th>Language</th></tr></thead><tbody><tr><td><code>en</code></td><td>English (default)</td></tr><tr><td><code>cs</code></td><td>Czech</td></tr><tr><td><code>de</code></td><td>German</td></tr><tr><td><code>es</code></td><td>Spanish</td></tr><tr><td><code>fr</code></td><td>French</td></tr><tr><td><code>pl</code></td><td>Polish</td></tr><tr><td><code>ro</code></td><td>Romanian</td></tr><tr><td><code>ru</code></td><td>Russian</td></tr></tbody></table><p>Restart MS_FlightSim after changing it. The language applies to notifications, menus, the tablet and most of the cockpit display.</p><p>Set it in <code>config.lua</code> itself, not in <code>config_overrides.lua</code>. The text, including aircraft, rank, malfunction and NPC names, is loaded while <code>config.lua</code> runs, before the overrides, so an override line comes too late to switch the language. An update replaces <code>config.lua</code>, so set the language again after updating.</p><h2 id="missing-text-falls-back-to-english" tabindex="-1">Missing text falls back to English <a class="header-anchor" href="#missing-text-falls-back-to-english" aria-label="Permalink to &quot;Missing text falls back to English&quot;">​</a></h2><p>Every language file is checked against English when the resource starts. Any line a translation doesn&#39;t have is shown in English. New lines are added to English first, so after an update a few new texts can appear in English until the translation catches up.</p><p>A few fixed cockpit labels, such as PFD SCALE in the CFG menu, are always in English.</p><h2 id="changing-a-single-line" tabindex="-1">Changing a single line <a class="header-anchor" href="#changing-a-single-line" aria-label="Permalink to &quot;Changing a single line&quot;">​</a></h2><p>Use <code>locales/zz_overrides.lua</code>. Updates never replace it.</p><ol><li><p>Rename <code>locales/zz_overrides.lua.example</code> to <code>locales/zz_overrides.lua</code>. Keep the <code>zz_</code> at the start: it makes the file load after every language file, so your text wins.</p></li><li><p>Find the line you want to change. Open the language file, for example <code>locales/en.lua</code>, and search for the text you see in game. The name on the left of the <code>=</code> is its key.</p></li><li><p>Set the new text for that key and language:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Locales </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Locales[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Locales[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shopTitle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Aircraft Sales&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Locales </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Locales[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;de&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Locales[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;de&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shopTitle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Flugzeugverkauf&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div></li><li><p>Restart MS_FlightSim.</p></li></ol><p>Change only the language your server uses; the others are never shown. Keep markers such as <code>%s</code>, <code>%d</code> and <code>%.0f</code> in the same order as the original, because the script fills numbers and names into them.</p><h2 id="adding-a-new-language" tabindex="-1">Adding a new language <a class="header-anchor" href="#adding-a-new-language" aria-label="Permalink to &quot;Adding a new language&quot;">​</a></h2><ol><li>Copy <code>locales/en.lua</code> and name the copy after your language code, for example <code>locales/it.lua</code>.</li><li>Near the top, change <code>Locales[&#39;en&#39;] = {</code> to your code: <code>Locales[&#39;it&#39;] = {</code>.</li><li>Translate the text on the right of each <code>=</code>. Never change the key names on the left, and keep every <code>%s</code>, <code>%d</code> and similar marker.</li><li>In <code>config.lua</code>, set <code>Config.Language = &#39;it&#39;</code>.</li><li>Restart MS_FlightSim.</li></ol><p>The new file is picked up automatically; you don&#39;t need to touch <code>fxmanifest.lua</code>. You can translate a part and leave the rest: anything missing shows in English.</p><p>Updates don&#39;t include your file, so it stays. After an update, compare it with the new <code>en.lua</code> and translate any new lines.</p><h2 id="atc-voice-is-english-only" tabindex="-1">ATC voice is English only <a class="header-anchor" href="#atc-voice-is-english-only" aria-label="Permalink to &quot;ATC voice is English only&quot;">​</a></h2><p>The tower&#39;s spoken radio calls and the cockpit&#39;s spoken warnings (&quot;Terrain&quot;, &quot;Stall&quot;, &quot;Traffic&quot;) are pre-recorded in English. They stay English whatever <code>Config.Language</code> is set to. Players can turn them down or off with the <strong>Callout sounds</strong> and <strong>ATC chatter</strong> sliders in the cockpit CFG menu.</p>`,21)])])}const k=a(n,[["render",l]]);export{p as __pageData,k as default};
